def transform(grid):
    out=[r[:] for r in grid]
    # The third example shows the rule: in the first patterned block, extend
    # the matching 3x3 motif row(s) to the right with color 1. The pattern is
    # repeated along the width in alternating 3-column groups; cells are filled
    # where the aligned corresponding row in the lower block is foreground.
    bg=max(set(v for row in grid for v in row),key=lambda v:sum(r.count(v) for r in grid))
    active=[i for i,row in enumerate(grid) if any(v!=bg for v in row)]
    blocks=[]
    for i in active:
        if not blocks or i>blocks[-1][-1]+1: blocks.append([i])
        else: blocks[-1].append(i)
    if len(blocks)>=2:
        top,bottom=blocks[0],blocks[1]
        # discover rightmost point of each upper row whose counterpart in the
        # lower pattern is foreground and complete the suffix from there.
        for k,r in enumerate(top):
            if k>=len(bottom): break
            r2=bottom[k]
            for c in range(len(grid[0])):
                if grid[r][c]==bg and grid[r2][c]!=bg: out[r][c]=1
    return out

