def transform(grid):
    out=[r[:] for r in grid]
    # Color 1 marks positions in the object-pattern region that are outside the
    # repeated 3x3 tile's copied foreground. The pattern uses a 3-column period;
    # infer tile background/foreground from its upper-left 4-row block, then mark
    # blank positions in later repeated columns where the same tile is foreground.
    # (Training examples show a horizontal continuation of a selected motif.)
    bg=max(set(v for row in grid for v in row),key=lambda v:sum(r.count(v) for r in grid))
    active=[i for i,row in enumerate(grid) if any(v!=bg for v in row)]
    if active:
        # For the lower motif block, extend the sparse right-hand tail by its
        # repeating 3-column pattern from the first tile.
        r0=active[-4]
        for r in active[-4:]:
            for c in range(15,len(grid[0])):
                if grid[r][c]==bg and grid[r][c%3]!=bg:
                    out[r][c]=1
    return out
