def transform(grid):
    out=[row[:] for row in grid]
    bg=max(set(v for row in grid for v in row), key=lambda v:sum(r.count(v) for r in grid))
    active=[i for i,row in enumerate(grid) if any(v!=bg for v in row)]
    blocks=[]
    for i in active:
        if not blocks or i>blocks[-1][-1]+1: blocks.append([i])
        else: blocks[-1].append(i)
    if len(blocks)>=2:
        first,second=blocks[:2]
        for r1,r2 in zip(first,second):
            end1=max((c for c,v in enumerate(grid[r1]) if v!=bg),default=-1)
            end2=max((c for c,v in enumerate(grid[r2]) if v!=bg),default=-1)
            # Extend the shorter row's missing right-hand continuation only.
            if end1>end2:
                for c in range(end2+1,end1+1):
                    if grid[r2][c]==bg and grid[r1][c]!=bg: out[r2][c]=1
            elif end2>end1:
                for c in range(end1+1,end2+1):
                    if grid[r1][c]==bg and grid[r2][c]!=bg: out[r1][c]=1
    return out
