def transform(grid):
    out=[row[:] for row in grid]
    # Only extend solid horizontal bars. Find the row with a solid run that
    # is shorter than a matching longer solid run elsewhere; color its tail 1.
    runs=[]
    for i,row in enumerate(grid):
        nz=[j for j,v in enumerate(row) if v!=0]
        if nz and nz==list(range(nz[0],nz[-1]+1)):
            runs.append((nz[0],nz[-1],i))
    if runs:
        # Choose the nearest pair of rows having same start and different ends.
        pairs=[]
        for a in runs:
            for b in runs:
                if a[2]!=b[2] and a[0]==b[0] and a[1]<b[1]: pairs.append((b[1]-a[1],a,b))
        if pairs:
            _,short,long=max(pairs)
            for c in range(short[1]+1,long[1]+1): out[short[2]][c]=1
    return out
