def transform(grid):
    out=[r[:] for r in grid]
    # Locate the left-hand repeated 3x3 pattern and its matching right-hand section.
    # The right-hand region is a repetition of the first 3-column motif; color 1
    # marks foreground cells in the continuation, while preserving existing cells.
    for r,row in enumerate(grid):
        if any(v!=0 for v in row):
            # The row-wise pattern period is 3; extend across the rightmost region
            # when the motif's equivalent cell is foreground.
            for c in range(15,len(row)):
                if row[c]==0 and row[c%3]!=0:
                    out[r][c]=1
    return out
