def transform(grid):
    out=[row[:] for row in grid]
    # Identify the two separated content bands, then copy the foreground
    # continuation into the shorter band's trailing portion as color 1.
    active=[i for i,row in enumerate(grid) if any(v!=0 for v in row)]
    bands=[]
    for i in active:
        if not bands or i>bands[-1][-1]+1: bands.append([i])
        else: bands[-1].append(i)
    if len(bands)>=2:
        top,bottom=bands[0],bands[1]
        # Complete each lower row from the upper row, using only the final
        # suffix beyond the lower pattern's last foreground.
        for u,l in zip(top,bottom):
            last_l=max((c for c,v in enumerate(grid[l]) if v!=0),default=-1)
            last_u=max((c for c,v in enumerate(grid[u]) if v!=0),default=-1)
            if last_u>last_l:
                for c in range(last_l+1,last_u+1):
                    if grid[u][c]!=0 and grid[l][c]==0: out[l][c]=1
    return out
