                    continue
                pos = [c for c, v in enumerate(other) if v != bg]
                if pos and pos == list(range(pos[0], pos[-1] + 1)) and pos[0] == vals[0] and pos[-1] > vals[-1]:
                    matches.append(pos[-1])
            if matches:
                for c in range(vals[-1] + 1, max(matches) + 1):
                    out[r][c] = 1
                break
    return out
